import { render, screen, waitFor } from '@testing-library/react'
import App from './App'

test('shows success after loading', async () => {
  render(<App />)

  expect(screen.getByRole('status')).toHaveTextContent('Loading')
  expect(await screen.findByRole('status')).toHaveTextContent('Success')

  await waitFor(() => {
    expect(screen.getByRole('button', { name: 'Retry' })).toBeEnabled()
  })
})

import {render, screen, waitFor} from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import App from './App'

test('shows the saved message', async () => {
  const user = userEvent.setup()
  render(<App />)

  await user.click(screen.getByRole('button', {name: /save/i}))
  expect(await screen.findByText('Saved')).toBeInTheDocument()

  await waitFor(() => {
    expect(screen.getByRole('status')).toHaveTextContent('Saved')
  })
})

import React from 'react'
import {render, screen, waitFor} from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import {MyForm} from './myForm'

test('submits entered form values', async () => {
  const handleSubmit = jest.fn()
  render(<MyForm onSubmit={handleSubmit} />)
  const user = userEvent.setup()

  await user.type(screen.getByRole('textbox', {name: /first name/i}), 'John')
  await user.type(screen.getByRole('textbox', {name: /last name/i}), 'Dee')
  await user.type(screen.getByRole('textbox', {name: /email/i}), 'john@example.com')
  await user.click(screen.getByRole('button', {name: /submit/i}))

  await waitFor(() => expect(handleSubmit).toHaveBeenCalledWith({
    firstName: 'John', lastName: 'Dee', email: 'john@example.com',
  }))
})

