import {render, screen} from '@testing-library/react'
import '@testing-library/jest-dom'

function Status() {
  return <div><p>Saved</p><span data-testid="sync-state">idle</span></div>
}

test('finds user-visible text and a semantic gap', () => {
  render(<Status />)
  expect(screen.getByText('Saved')).toBeInTheDocument()
  expect(screen.getByTestId('sync-state')).toHaveTextContent('idle')
})

import {render, within} from '@testing-library/react'
import {screen} from '@testing-library/react'

function Cards() {
  return <section aria-label="Messages"><button>Archive</button></section>
}

test('finds a control inside the messages region', () => {
  render(<Cards />)
  const messages = screen.getByRole('region', {name: 'Messages'})
  expect(within(messages).getByRole('button', {name: 'Archive'})).toBeInTheDocument()
})

import {render, screen} from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import '@testing-library/jest-dom'
import Toggle from './Toggle'

test('toggle is keyboard accessible and exposes state', async () => {
  const user = userEvent.setup()
  render(<Toggle />)
  const toggle = screen.getByRole('button', {name: /notifications/i})
  expect(toggle).toHaveAttribute('aria-pressed', 'false')
  await user.tab()
  await user.keyboard('{Enter}')
  expect(toggle).toHaveAttribute('aria-pressed', 'true')
})
